// store wraps *Mem and adds Delete, so the value satisfies Store.
// Deleted keys are tracked as tombstones and hidden from Get.
type store struct {
	*Mem
	deleted map[string]bool
}

func (s *store) Put(k, v string) {
	delete(s.deleted, k)
	s.Mem.Put(k, v)
}

func (s *store) Get(k string) (string, bool) {
	if s.deleted[k] {
		return "", false
	}
	return s.Mem.Get(k)
}

func (s *store) Delete(k string) {
	s.deleted[k] = true
}

func use(s Store) {
	s.Put("a", "1")
	v, ok := s.Get("a")
	fmt.Println(v, ok)
	s.Delete("a")
	_, ok = s.Get("a")
	fmt.Println(ok)
}

func main() {
	use(&store{Mem: NewMem(), deleted: map[string]bool{}})
}

