import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

// FormatName trims surrounding whitespace from each part and joins the
// non-empty parts with a single space, e.g. " Ada", "Lovelace " -> "Ada Lovelace".
// Defined locally because textutil.FormatName is not available in the module.
func FormatName(parts ...string) string {
	var out []string
	for _, p := range parts {
		if t := strings.TrimSpace(p); t != "" {
			out = append(out, t)
		}
	}
	return strings.Join(out, " ")
}

// Initial returns the upper-cased first letter of each part concatenated,
// e.g. "ada", "lovelace" -> "AL".
// Defined locally because textutil.Initial is not available in the module.
func Initial(parts ...string) string {
	var b strings.Builder
	for _, p := range parts {
		r, size := utf8.DecodeRuneInString(p)
		if size == 0 || r == utf8.RuneError {
			continue
		}
		b.WriteRune(unicode.ToUpper(r))
	}
	return b.String()
}

func main() {
	fmt.Println(FormatName(" Ada", "Lovelace "), Initial("ada", "lovelace"))
}

