import (
	"fmt"
)

type Cache struct {
	capacity int
	items    map[string]int
	order    []string
}

func NewCache(capacity int) *Cache {
	return &Cache{
		capacity: capacity,
		items:    make(map[string]int),
	}
}

func (c *Cache) Put(key string, value int) {
	if _, ok := c.items[key]; ok {
		c.items[key] = value
		return
	}
	if len(c.items) >= c.capacity && c.capacity > 0 {
		oldest := c.order[0]
		c.order = c.order[1:]
		delete(c.items, oldest)
	}
	if c.capacity > 0 {
		c.items[key] = value
		c.order = append(c.order, key)
	}
}

func (c *Cache) Len() int {
	return len(c.items)
}

func main() {
	c := NewCache(2)
	c.Put("a", 1)
	c.Put("b", 2)
	c.Put("c", 3)
	fmt.Println(c.Len())
}

